// CreateTableWithDBType creates the General_Ledger_Setup table for the specified company with the given database type
// The db parameter can be either *sql.DB or *sql.Tx
func (t *GeneralLedgerSetup) CreateTableWithDBType(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, GeneralLedgerSetupTableName)
	var schema string
	if dbType == database.DBTypePostgres {
		schema = GetGeneralLedgerSetupPostgresTableSchema()
	} else {
		schema = GetGeneralLedgerSetupTableSchema()
	}

	createSQL := fmt.Sprintf(`CREATE TABLE IF NOT EXISTS "%s" (%s)`, tableName, schema)
	_, err := db.Exec(createSQL)
	if err != nil {
		return fmt.Errorf("failed to create General_Ledger_Setup table: %w", err)
	}

	// Indexes (Keys) and SIFT totals
	return t.SyncKeys(db, company, dbType)
}

// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *GeneralLedgerSetup) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, GeneralLedgerSetupTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (primary_key)`,
		fmt.Sprintf("%s$General_Ledger_Setup$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	var keys []sift.Key
	for _, spec := range generalLedgerSetupSIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, GeneralLedgerSetupTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, GeneralLedgerSetupTableName, keys)
}

// generalLedgerSetupSIFTSpecs are the table's keys with sum_index_fields
func generalLedgerSetupSIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *GeneralLedgerSetup) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := fmt.Sprintf("%s$%s", t.company, GeneralLedgerSetupTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range generalLedgerSetupSIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, GeneralLedgerSetupTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: GeneralLedgerSetupTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, GeneralLedgerSetupTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

