// hasFieldChanged checks if a field value has changed from oldValues
func (t *GeneralLedgerSetup) hasFieldChanged(fieldName string) bool {
	if t.oldValues == nil {
		return true // No old values, assume changed
	}

	oldValue, exists := t.oldValues[fieldName]
	if !exists {
		return true // Field not in old values, assume changed
	}
	_ = oldValue // Suppress unused variable when all fields are PKs

	// Compare old vs new value based on field name (with type assertion)
	switch fieldName {
	case "primary_key":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Primary_key.Equal(old)
		}
	case "allow_posting_from":
		if old, ok := oldValue.(types.Date); ok {
			return !t.Allow_posting_from.Equal(old)
		}
	case "allow_posting_to":
		if old, ok := oldValue.(types.Date); ok {
			return !t.Allow_posting_to.Equal(old)
		}
	case "register_time":
		if old, ok := oldValue.(bool); ok {
			return t.Register_time != old
		}
		return true // Type mismatch, assume changed
	case "pmt_disc_excl_tax":
		if old, ok := oldValue.(bool); ok {
			return t.Pmt_disc_excl_tax != old
		}
		return true // Type mismatch, assume changed
	case "unrealized_tax":
		if old, ok := oldValue.(bool); ok {
			return t.Unrealized_tax != old
		}
		return true // Type mismatch, assume changed
	case "adjust_for_payment_disc":
		if old, ok := oldValue.(bool); ok {
			return t.Adjust_for_payment_disc != old
		}
		return true // Type mismatch, assume changed
	case "mark_cr_memos_as_corrections":
		if old, ok := oldValue.(bool); ok {
			return t.Mark_cr_memos_as_corrections != old
		}
		return true // Type mismatch, assume changed
	case "local_address_format":
		if old, ok := oldValue.(GeneralLedgerSetupLocal_address_format); ok {
			return t.Local_address_format != old
		}
	case "inv_rounding_precision_lcy":
		if old, ok := oldValue.(types.Decimal); ok {
			return !t.Inv_rounding_precision_lcy.Equal(old)
		}
	case "inv_rounding_type_lcy":
		if old, ok := oldValue.(GeneralLedgerSetupInv_rounding_type_lcy); ok {
			return t.Inv_rounding_type_lcy != old
		}
	case "local_cont_addr_format":
		if old, ok := oldValue.(GeneralLedgerSetupLocal_cont_addr_format); ok {
			return t.Local_cont_addr_format != old
		}
	case "recalculate_sales_tax":
		if old, ok := oldValue.(bool); ok {
			return t.Recalculate_sales_tax != old
		}
		return true // Type mismatch, assume changed
	case "summarize_gl_entries":
		if old, ok := oldValue.(bool); ok {
			return t.Summarize_gl_entries != old
		}
		return true // Type mismatch, assume changed
	case "amount_decimal_places":
		if old, ok := oldValue.(types.Text); ok {
			return !t.Amount_decimal_places.Equal(old)
		}
	case "unit_amount_decimal_places":
		if old, ok := oldValue.(types.Text); ok {
			return !t.Unit_amount_decimal_places.Equal(old)
		}
	case "additional_reporting_currency":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Additional_reporting_currency.Equal(old)
		}
	case "vat_tolerance_percent":
		if old, ok := oldValue.(types.Decimal); ok {
			return !t.Vat_tolerance_percent.Equal(old)
		}
	case "emu_currency":
		if old, ok := oldValue.(bool); ok {
			return t.Emu_currency != old
		}
		return true // Type mismatch, assume changed
	case "lcy_code":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Lcy_code.Equal(old)
		}
	case "tax_exchange_rate_adjustment":
		if old, ok := oldValue.(GeneralLedgerSetupTax_exchange_rate_adjustment); ok {
			return t.Tax_exchange_rate_adjustment != old
		}
	case "amount_rounding_precision":
		if old, ok := oldValue.(types.Decimal); ok {
			return !t.Amount_rounding_precision.Equal(old)
		}
	case "unit_amount_rounding_precision":
		if old, ok := oldValue.(types.Decimal); ok {
			return !t.Unit_amount_rounding_precision.Equal(old)
		}
	case "appln_rounding_precision":
		if old, ok := oldValue.(types.Decimal); ok {
			return !t.Appln_rounding_precision.Equal(old)
		}
	}

	return false
}

// SetDB changes the database executor of the record without touching its values — e.g. to
// run a Modify (with its rename cascade) inside a transaction.
func (t *GeneralLedgerSetup) SetDB(db database.Executor) {
	t.db = db
}

// Delete removes the record from the database
func (t *GeneralLedgerSetup) Delete(runTrigger bool) bool {
	// OnDelete trigger of the business logic
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnDelete(); err != nil {
			fmt.Printf("Error: OnDelete trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, GeneralLedgerSetupTableName)

	// Collect arguments for DELETE
	args := []interface{}{
		t.Primary_key,
	}

	// Build SQL with placeholders
	sqlStr := fmt.Sprintf(`DELETE FROM "%s" WHERE 1=1 AND primary_key = ?`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))

	_, err := t.exec().Exec(sqlStr, args...)
	if err != nil {
		fmt.Printf("Error: Failed to delete General_Ledger_Setup: %v\n", err)
		return false
	}
	return true
}

// ========================================
// FlowField Calculations
// ========================================

// CalcFields calculates FlowField values
// Usage:
//
//	customer.CalcFields("balance", "balance_lcy") - Calculate specific fields
//	customer.CalcFields() - Calculate all FlowFields
func (t *GeneralLedgerSetup) CalcFields(fieldNames ...string) {
	// If no field names specified, calculate all FlowFields
	if len(fieldNames) == 0 {
		t.calcFlowField_cust_balances_due()
		return
	}

	// Calculate only specified fields
	for _, fieldName := range fieldNames {
		switch fieldName {
		case "cust_balances_due":
			t.calcFlowField_cust_balances_due()
		}
	}
}

// calcFlowField_cust_balances_due calculates the cust_balances_due FlowField
// CalcFormula: Sum(CustomerLedgerEntry.remaining_amt_lcy)
func (t *GeneralLedgerSetup) calcFlowField_cust_balances_due() {
	t.Cust_balances_due = t.calcSum_cust_balances_due()
}

// CalcFieldsForRecords calculates FlowFields for many records at once (list pages):
// one grouped query per FlowField instead of one query per record. records are
// ToMap() results; each gets its FlowField values under the field name. With no
// field names, all FlowFields are calculated.
func (t *GeneralLedgerSetup) CalcFieldsForRecords(records []map[string]interface{}, fieldNames ...string) {
	if len(records) == 0 {
		return
	}
	if len(fieldNames) == 0 {
		fieldNames = t.GetFlowFields()
	}
	for _, fieldName := range fieldNames {
		switch fieldName {
		case "cust_balances_due":
			t.calcForRecords_cust_balances_due(records)
		}
	}
}

// calcForRecords_cust_balances_due calculates the cust_balances_due FlowField for a set of records
// CalcFormula: Sum(CustomerLedgerEntry.remaining_amt_lcy)
func (t *GeneralLedgerSetup) calcForRecords_cust_balances_due(records []map[string]interface{}) {
	// No single key field to group by: calculate per record
	for _, rec := range records {
		r := &GeneralLedgerSetup{db: t.db, company: t.company, dbType: t.dbType}
		r.FromMap(rec)
		r.calcFlowField_cust_balances_due()
		rec["cust_balances_due"] = r.Cust_balances_due.String()
	}
}

// Helper methods for FlowField calculations

func (t *GeneralLedgerSetup) calcSum_cust_balances_due() types.Decimal {
	// Source: the SIFT totals table of a key covering the filters, else the entries
	tableName, useSIFT := fmt.Sprintf("%s$%s", t.company, CustomerLedgerEntryTableName), false
	tableName, useSIFT = sift.TableName(t.company, CustomerLedgerEntryTableName, "customer_open"), true
	if t.Department_filter != "" || t.Project_filter != "" || t.Date_filter != "" {
		// A FlowFilter is set: the key must contain the filtered fields too
		tableName, useSIFT = fmt.Sprintf("%s$%s", t.company, CustomerLedgerEntryTableName), false
	}
	_ = useSIFT

	// Build WHERE clause from FlowFilters
	var whereClauses []string
	var args []interface{}
	whereClauses = append(whereClauses, "open = ?")
	args = append(args, true)
	if t.Department_filter != "" {
		// FlowFilter department_filter applied to department_code (validated by SetFlowFilter)
		if clause, filterArgs, _ := flowfilter.Clause("department_code", flowfilter.KindCode, t.Department_filter); clause != "" {
			whereClauses = append(whereClauses, clause)
			args = append(args, filterArgs...)
		}
	}
	if t.Project_filter != "" {
		// FlowFilter project_filter applied to project_code (validated by SetFlowFilter)
		if clause, filterArgs, _ := flowfilter.Clause("project_code", flowfilter.KindCode, t.Project_filter); clause != "" {
			whereClauses = append(whereClauses, clause)
			args = append(args, filterArgs...)
		}
	}
	if t.Date_filter != "" {
		// FlowFilter date_filter applied to due_date (validated by SetFlowFilter)
		if clause, filterArgs, _ := flowfilter.Clause("due_date", flowfilter.KindDate, t.Date_filter); clause != "" {
			whereClauses = append(whereClauses, clause)
			args = append(args, filterArgs...)
		}
	}

	whereClause := "1=1"
	if len(whereClauses) > 0 {
		whereClause = strings.Join(whereClauses, " AND ")
	}

	query := fmt.Sprintf(`SELECT COALESCE(SUM(remaining_amt_lcy), 0) FROM "%s" WHERE %s`, tableName, whereClause)

	// Convert placeholders for PostgreSQL
	query = t.convertPlaceholders(query, len(args))

	var sumStr string
	err := t.db.QueryRow(query, args...).Scan(&sumStr)
	if err != nil {
		fmt.Printf("Error: Failed to calculate sum for cust_balances_due: %v\n", err)
		return types.ZeroDecimal()
	}

	sum, _ := types.NewDecimalFromString(sumStr)
	return sum
}

