// Filtering and Search
// ========================================

// generalLedgerSetupFilterCondition represents a filter on a field
type generalLedgerSetupFilterCondition struct {
	fieldName    string
	minValue     interface{}
	maxValue     interface{}
	filterExpr   string // For complex SetFilter expressions
	isExpression bool   // True if using filterExpr instead of min/max
	invalidField bool   // Filter on an unknown field: matches no rows (fail closed)
	blankDate    bool   // A date range from the blank date: blank dates (NULL) match too
	flowField    string // Filter on a FlowField (filterExpr applied to its subquery)
}

// SetRange sets a range filter on a field
// Usage:
//
//	SetRange("No", "10000") - exact match (No = "10000")
//	SetRange("No", "10000", "20000") - range (No between "10000" and "20000")
//	SetRange("No") - removes the filter on the field
func (t *GeneralLedgerSetup) SetRange(fieldName string, values ...interface{}) {
	if t.filters == nil {
		t.filters = make(map[string]*generalLedgerSetupFilterCondition)
	}

	var minValue, maxValue interface{}

	switch len(values) {
	case 0:
		if column, ok := t.columnName(fieldName); ok {
			delete(t.filters, column)
		}
		delete(t.filters, fieldName)
		return
	case 1:
		// Exact match: SetRange("No", "10000")
		minValue = values[0]
		maxValue = values[0]
	case 2:
		// Range: SetRange("No", "10000", "20000")
		minValue = values[0]
		maxValue = values[1]
	default:
		fmt.Printf("Error: SetRange requires 1 or 2 values, got %d\n", len(values))
		return
	}

	column, ok := t.columnName(fieldName)
	if !ok {
		// Unknown field: fail closed (no rows) rather than drop the filter or put
		// the name into SQL
		fmt.Printf("Error: SetRange on unknown field %q of General_Ledger_Setup\n", fieldName)
		t.filters[fieldName] = &generalLedgerSetupFilterCondition{invalidField: true}
		return
	}

	// Blank dates are stored as NULL and come before every date: a range from the blank date
	// (or the blank date itself) matches them
	blankDate := false
	if d, ok := values[0].(types.Date); ok && d.IsZero() {
		blankDate = true
		minValue = nil
		if len(values) == 1 {
			maxValue = nil
		}
	}

	t.filters[column] = &generalLedgerSetupFilterCondition{
		fieldName: column,
		minValue:  minValue,
		maxValue:  maxValue,
		blankDate: blankDate,
	}
}

// SetFilter sets a complex filter expression on a field
// Supports filter syntax: "100..200|500" (range OR exact value)
// Operators: .. (range), | (OR), & (AND), * (wildcard), <> (not equal)
// Example: customer.SetFilter("No", "001..003|005")
func (t *GeneralLedgerSetup) SetFilter(fieldName, filterExpr string) {
	if t.filters == nil {
		t.filters = make(map[string]*generalLedgerSetupFilterCondition)
	}
	if _, ok := t.FlowFieldFilterKind(fieldName); ok {
		// A FlowField is not a column: the filter applies to its subquery (flowFieldExpr)
		name := strings.ToLower(fieldName)
		t.filters["flowfield:"+name] = &generalLedgerSetupFilterCondition{
			flowField:    name,
			filterExpr:   filterExpr,
			isExpression: true,
		}
		return
	}
	column, ok := t.columnName(fieldName)
	if !ok {
		// Unknown field: fail closed (no rows) rather than drop the filter or put
		// the name into SQL
		fmt.Printf("Error: SetFilter on unknown field %q of General_Ledger_Setup\n", fieldName)
		t.filters[fieldName] = &generalLedgerSetupFilterCondition{invalidField: true}
		return
	}
	t.filters[column] = &generalLedgerSetupFilterCondition{
		fieldName:    column,
		filterExpr:   filterExpr,
		isExpression: true,
	}
}

// FlowFieldFilterKind reports whether a list can be filtered on FlowField field (Sum and
// Count FlowFields: SETFILTER on a FlowField) and the kind of its values.
func (t *GeneralLedgerSetup) FlowFieldFilterKind(field string) (flowfilter.Kind, bool) {
	switch strings.ToLower(field) {
	case "cust_balances_due":
		return flowfilter.KindDecimal, true
	}
	return "", false
}

// flowFieldExpr is the SQL expression computing FlowField field for each row of a query
// on this table: a correlated subquery reading the source like CalcFieldsForRecords (the
// SIFT totals of a covering key, else the entries), with the FlowFilters set on t.
func (t *GeneralLedgerSetup) flowFieldExpr(field string) (string, []interface{}) {
	outer := "\"" + fmt.Sprintf("%s$%s", t.company, GeneralLedgerSetupTableName) + "\""
	_ = outer
	switch strings.ToLower(field) {
	case "cust_balances_due":
		// Source: the SIFT totals table of a key covering the filters, else the entries
		tableName, useSIFT := fmt.Sprintf("%s$%s", t.company, CustomerLedgerEntryTableName), false
		tableName, useSIFT = sift.TableName(t.company, CustomerLedgerEntryTableName, "customer_open"), true
		if t.Department_filter != "" || t.Project_filter != "" || t.Date_filter != "" {
			// A FlowFilter is set: the key must contain the filtered fields too
			tableName, useSIFT = fmt.Sprintf("%s$%s", t.company, CustomerLedgerEntryTableName), false
		}
		_ = useSIFT
		var whereClauses []string
		var args []interface{}
		whereClauses = append(whereClauses, "open = ?")
		args = append(args, true)
		if t.Department_filter != "" {
			// FlowFilter department_filter applied to department_code (validated by SetFlowFilter)
			if clause, filterArgs, _ := flowfilter.Clause("department_code", flowfilter.KindCode, t.Department_filter); clause != "" {
				whereClauses = append(whereClauses, clause)
				args = append(args, filterArgs...)
			}
		}
		if t.Project_filter != "" {
			// FlowFilter project_filter applied to project_code (validated by SetFlowFilter)
			if clause, filterArgs, _ := flowfilter.Clause("project_code", flowfilter.KindCode, t.Project_filter); clause != "" {
				whereClauses = append(whereClauses, clause)
				args = append(args, filterArgs...)
			}
		}
		if t.Date_filter != "" {
			// FlowFilter date_filter applied to due_date (validated by SetFlowFilter)
			if clause, filterArgs, _ := flowfilter.Clause("due_date", flowfilter.KindDate, t.Date_filter); clause != "" {
				whereClauses = append(whereClauses, clause)
				args = append(args, filterArgs...)
			}
		}
		where := "1=1"
		if len(whereClauses) > 0 {
			where = strings.Join(whereClauses, " AND ")
		}
		agg := "COALESCE(SUM(remaining_amt_lcy), 0)"
		return "(SELECT " + agg + " FROM \"" + tableName + "\" WHERE " + where + ")", args
	}
	return "NULL", nil
}

// SetCurrentKey sets the sort order for queries
// Unknown fields are ignored (the primary key order is used if none remain).
// Example: customer.SetCurrentKey("City", "Name")
func (t *GeneralLedgerSetup) SetCurrentKey(fields ...string) {
	t.orderByFields = nil
	for _, field := range fields {
		// A Sum/Count FlowField sorts on its calculated value (flowFieldExpr, see getOrderByClause)
		if _, ok := t.FlowFieldFilterKind(field); ok {
			t.orderByFields = append(t.orderByFields, "flowfield:"+strings.ToLower(field))
			continue
		}
		column, ok := t.columnName(field)
		if !ok {
			fmt.Printf("Error: SetCurrentKey on unknown field %q of General_Ledger_Setup\n", field)
			continue
		}
		t.orderByFields = append(t.orderByFields, column)
	}
}

